// Shopify Morning Check (free version): paid orders that haven't shipped + variants running low, in one email.
// No dependencies. `gql(query, variables)` is injected so the same code runs inside n8n and in tests.

const Q_SHOP = `query { shop { name myshopifyDomain ianaTimezone currencyCode } }`;

const Q_STUCK = `query($q: String!, $after: String) {
  orders(first: 50, after: $after, query: $q, sortKey: CREATED_AT) {
    pageInfo { hasNextPage endCursor }
    nodes { id name createdAt totalPriceSet { shopMoney { amount } } customer { displayName } }
  }
}`;

const Q_LOW_STOCK = `query($q: String!, $after: String) {
  productVariants(first: 100, after: $after, query: $q) {
    pageInfo { hasNextPage endCursor }
    nodes { id title sku inventoryQuantity inventoryItem { tracked } product { id title status } }
  }
}`;

async function paginate(gql, query, vars, key, maxItems) {
  const out = [];
  let after = null;
  for (;;) {
    const conn = (await gql(query, { ...vars, after }))[key];
    out.push(...conn.nodes);
    if (!conn.pageInfo.hasNextPage || out.length >= maxItems) break;
    after = conn.pageInfo.endCursor;
  }
  return out.slice(0, maxItems);
}

async function fetchCheck(gql, cfg, now) {
  const shop = (await gql(Q_SHOP, {})).shop;
  const cutoff = new Date(now.getTime() - cfg.stuck_after_hours * 3600000).toISOString().replace('.000Z', 'Z');
  const stuck = await paginate(gql, Q_STUCK, {
    q: `financial_status:paid AND status:open AND (fulfillment_status:unshipped OR fulfillment_status:partial) AND created_at:<'${cutoff}'`,
  }, 'orders', 250);
  const lowStock = await paginate(gql, Q_LOW_STOCK, { q: `inventory_quantity:<=${cfg.low_stock_threshold}` }, 'productVariants', 500);
  return { shop, now: now.toISOString(), stuck, lowStock };
}

function analyzeCheck(data, cfg) {
  const now = Date.parse(data.now);
  const stuck = data.stuck
    .map(o => ({ id: o.id, name: o.name, customer: o.customer ? o.customer.displayName : '', total: Number(o.totalPriceSet.shopMoney.amount),
      hours: Math.floor((now - Date.parse(o.createdAt)) / 3600000) }))
    .sort((a, b) => b.hours - a.hours);
  const lowStock = data.lowStock
    .filter(v => !(v.inventoryItem && v.inventoryItem.tracked === false))
    .filter(v => !v.product || !v.product.status || v.product.status === 'ACTIVE')
    .filter(v => cfg.include_sold_out || v.inventoryQuantity > 0)
    .map(v => ({ id: v.id, product: v.product.title, variant: v.title === 'Default Title' ? '' : v.title, sku: v.sku, onHand: v.inventoryQuantity }))
    .sort((a, b) => a.onHand - b.onHand);
  const domain = String(data.shop.myshopifyDomain || '').replace('.myshopify.com', '');
  return { shop: { name: data.shop.name, currency: data.shop.currencyCode, adminBase: `https://admin.shopify.com/store/${domain}` },
    stuck, lowStock, threshold: cfg.low_stock_threshold, stuckAfter: cfg.stuck_after_hours };
}

function fmtMoney(v, cur) {
  try { return new Intl.NumberFormat('en-US', { style: 'currency', currency: cur || 'USD' }).format(v); }
  catch (e) { return `${cur || ''} ${Number(v).toFixed(2)}`; }
}

function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function subjectCheck(c) {
  const parts = [];
  if (c.stuck.length) parts.push(`${c.stuck.length} unshipped order${c.stuck.length > 1 ? 's' : ''}`);
  if (c.lowStock.length) parts.push(`${c.lowStock.length} low-stock variant${c.lowStock.length > 1 ? 's' : ''}`);
  return `${c.shop.name}: ${parts.length ? parts.join(', ') : 'all clear'}`;
}

function renderCheck(c) {
  const C = { ink: '#1a1a1a', muted: '#6b6b6b', line: '#e6e6e6', bg: '#f6f6f4', red: '#b42318', green: '#067647' };
  const table = (heads, rows) => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;font-size:13px">
<tr>${heads.map((h, i) => `<th style="text-align:${i ? 'right' : 'left'};color:${C.muted};font-weight:600;padding:6px 0;border-bottom:1px solid ${C.line}">${h}</th>`).join('')}</tr>
${rows.map(r => `<tr>${r.map((v, i) => `<td style="text-align:${i ? 'right' : 'left'};padding:7px 0;border-bottom:1px solid ${C.line};color:${C.ink}">${v}</td>`).join('')}</tr>`).join('')}</table>`;
  const section = (title, body) => `<tr><td style="padding:18px 24px 4px;font-size:15px;font-weight:700;color:${C.ink}">${title}</td></tr><tr><td style="padding:4px 24px 8px">${body}</td></tr>`;
  const ok = text => `<div style="font-size:14px;color:${C.green}">${text}</div>`;
  const link = o => `<a href="${c.shop.adminBase}/orders/${String(o.id).split('/').pop()}" style="color:${C.ink}">${esc(o.name)}</a>`;

  let html = `<!doctype html><html><head><meta charset="utf-8"></head><body style="margin:0;background:${C.bg};font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:24px 12px">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background:#fff;border-radius:12px">
<tr><td style="padding:22px 24px 4px;font-size:13px;color:${C.muted}">${esc(c.shop.name)} · Morning Check</td></tr>`;
  html += section(`Paid but not shipped after ${c.stuckAfter}h (${c.stuck.length})`, c.stuck.length
    ? table(['Order', 'Customer', 'Waiting', 'Total'], c.stuck.slice(0, 25).map(o => [link(o), esc(o.customer || '—'),
      o.hours >= 48 ? `${Math.floor(o.hours / 24)} days` : `${o.hours} h`, fmtMoney(o.total, c.shop.currency)]))
    : ok('Nothing waiting. Every paid order has shipped.'));
  html += section(`Stock at or below ${c.threshold} units (${c.lowStock.length})`, c.lowStock.length
    ? table(['Product', 'On hand'], c.lowStock.slice(0, 40).map(s => [`${esc(s.product)}${s.variant ? ` <span style="color:${C.muted}">· ${esc(s.variant)}</span>` : ''}`,
      s.onHand <= 0 ? `<b style="color:${C.red}">${s.onHand}</b>` : String(s.onHand)]))
    : ok('No tracked variant is running low.'));
  html += `<tr><td style="padding:16px 24px 22px;font-size:11px;color:${C.muted}">Active products with tracked inventory only. Thresholds live in the Config node.</td></tr>
</table></td></tr></table></body></html>`;
  return html;
}

const DEFAULTS = { stuck_after_hours: 48, low_stock_threshold: 5, include_sold_out: false, api_version: '2026-07' };

function withDefaults(cfg) {
  const out = { ...DEFAULTS };
  for (const [k, v] of Object.entries(cfg || {})) if (v !== '' && v !== null && v !== undefined) out[k] = v;
  out.stuck_after_hours = Number(out.stuck_after_hours);
  out.low_stock_threshold = Number(out.low_stock_threshold);
  out.include_sold_out = out.include_sold_out === true || out.include_sold_out === 'true';
  return out;
}

// ---------------------------------------------------------------

const cfg = withDefaults($('Config').first().json);
const d = String(cfg.shop_domain || '').trim().replace(/\/+$/, '');
if (!d || d === 'your-store.myshopify.com') throw new Error('Set shop_domain in the Config node (e.g. my-shop.myshopify.com).');
const base = /^https?:\/\//.test(d) ? d : 'https://' + d;
const token = $('Get Shopify access token').first().json.access_token;
if (!token) throw new Error('Shopify did not return an access token. Check the Client ID/secret in the Custom Auth credential.');
const sleep = ms => new Promise(r => setTimeout(r, ms));

const gql = async (query, variables) => {
  for (let attempt = 1; attempt <= 5; attempt++) {
    let res;
    try {
      res = await this.helpers.httpRequest({
        method: 'POST',
        url: `${base}/admin/api/${cfg.api_version}/graphql.json`,
        headers: { 'X-Shopify-Access-Token': token, 'Content-Type': 'application/json' },
        body: { query, variables },
        json: true,
        timeout: 60000,
      });
    } catch (e) {
      const status = String(e.httpCode || (e.response && e.response.status) || '');
      if ((status === '429' || status.startsWith('5')) && attempt < 5) { await sleep(1500 * attempt); continue; }
      throw e;
    }
    if (res.errors) {
      const text = JSON.stringify(res.errors);
      if (text.includes('THROTTLED') && attempt < 5) { await sleep(2000 * attempt); continue; }
      if (text.includes('ACCESS_DENIED')) throw new Error('Missing access scope. The app needs read_orders, read_products and read_inventory.');
      throw new Error('Shopify API error: ' + text.slice(0, 500));
    }
    return res.data;
  }
  throw new Error('Shopify kept rate-limiting the requests. Try again later.');
};

const check = analyzeCheck(await fetchCheck(gql, cfg, new Date()), cfg);
return [{ json: { subject: subjectCheck(check), html: renderCheck(check), stuck: check.stuck.length, low_stock: check.lowStock.length } }];
